async function addParsedRaster(r,name,opt={}){await rasterLibs();const st=rasterRange(r),pal=opt.palette||((name||"").match(/NDVI|SAVI|EVI/i)?"ndvi":(name||"").match(/NDWI|MNDWI/i)?"water":"terrain"),layer=new GeoRasterLayer({georaster:r,opacity:opt.opacity??.72,resolution:opt.resolution||96,updateWhenZooming:false,updateWhenIdle:true,keepBuffer:4,pixelValuesToColorFn:v=>{const x=v?.[0];if(!Number.isFinite(x)||x===r.noDataValue)return null;return interpColor(x,st.min,st.max,pal)}});layer.addTo(map);const item={id:uid(),name:safe(name,"Raster"),georaster:r,layer,stats:st,palette:pal,visible:true,opacity:opt.opacity??.72};rasterRegistry.push(item);activeRaster=item;if(opt.fit!==false)try{map.fitBounds(layer.getBounds())}catch{}renderRasters();updateLegend();refreshAnalysisSelectors();toast(`تمت إضافة ${item.name}`,"ok");return item}
