async function importRasterFile(f){if(!f)return;const b=$("#importRaster");busy(b,true,"قراءة GeoTIFF...");try{await addRasterBuffer(await f.arrayBuffer(),f.name)}catch(e){console.error(e);toast(`تعذر فتح الراستر: ${e.message}`,"err",5000)}finally{busy(b,false);$("#rasterFile").value=""}}
function renderRasters(){const box=$("#rasterList");box.replaceChildren();if(!rasterRegistry.length){box.innerHTML='<div class="empty">لا توجد طبقات Raster</div>';return}for(const r of [...rasterRegistry].reverse()){const d=document.createElement("div");d.className="rasteritem";const h=document.createElement("div");h.className="rasterhead";h.innerHTML=`<i class="fa-solid fa-image" style="color:#7c3aed"></i><strong></strong>`;$("strong",h).textContent=r.name;const ops=document.createElement("div");ops.className="rasterops";const mk=(ic,fn,t)=>{const q=document.createElement("button");q.title=t;q.innerHTML=`<i class="fa-solid ${ic}"></i>`;q.onclick=fn;return q};ops.append(mk(r.visible?"fa-eye":"fa-eye-slash",()=>{r.visible=!r.visible;r.visible?r.layer.addTo(map):map.removeLayer(r.layer);renderRasters();updateLegend()},"إظهار/إخفاء"),mk("fa-crosshairs",()=>{activeRaster=r;try{map.fitBounds(r.layer.getBounds())}catch{}toast(`الراستر النشط: ${r.name}`,"info")},"تحديد"),mk("fa-trash",()=>{map.removeLayer(r.layer);rasterRegistry.splice(rasterRegistry.indexOf(r),1);if(activeRaster===r)activeRaster=rasterRegistry.at(-1)||null;renderRasters();updateLegend();refreshAnalysisSelectors()},"حذف"));h.append(ops);const m=document.createElement("div");m.className="rastermeta";m.textContent=`${r.georaster.width}×${r.georaster.height} | Min ${r.stats.min.toFixed(2)} | Max ${r.stats.max.toFixed(2)} | Mean ${r.stats.mean.toFixed(2)}`;const range=document.createElement("input");range.type="range";range.min=.05;range.max=1;range.step=.05;range.value=r.opacity;range.oninput=e=>{r.opacity=+e.target.value;r.layer.setOpacity(r.opacity)};d.append(h,m,range);box.append(d)}}
function updateLegend(){const box=$("#legendItems");if(!box)return;box.replaceChildren();layers.eachLayer(l=>{if(l._customVisible===false)return;const row=document.createElement("div");row.className="legi";const sym=document.createElement("span"),s=style(l),ty=type(l);sym.className=ty==="Point"?"legpt":"legsym";sym.style.background=ty==="Point"?"#dc2626":(s.fillColor||s.color||"#2563eb");sym.style.borderColor=s.color||"#2563eb";row.append(sym,document.createTextNode(l.customName||ty));box.append(row)});for(const r of rasterRegistry.filter(x=>x.visible)){const row=document.createElement("div");row.className="legi";const sym=document.createElement("span");sym.className="legsym";sym.style.background=`linear-gradient(90deg,${(palettes[r.palette]||palettes.terrain).join(",")})`;row.append(sym,document.createTextNode(`${r.name} (${r.stats.min.toFixed(1)}–${r.stats.max.toFixed(1)})`));box.append(row)}if(!box.children.length)box.textContent="لا توجد طبقات ظاهرة";$("#printLegendView")&&($("#printLegendView").innerHTML=$("#legendBox").innerHTML.replace(/<button[\s\S]*?<\/button>/,""))}
function initMiniMap(){if(miniMapObj)return;miniMapObj=L.map("miniMap",{zoomControl:false,attributionControl:false,dragging:false,scrollWheelZoom:false,doubleClickZoom:false,boxZoom:false,keyboard:false,tap:false}).setView(map.getCenter(),Math.max(2,map.getZoom()-4));L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:18}).addTo(miniMapObj);miniRect=L.rectangle(map.getBounds(),{color:"#dc2626",weight:2,fill:false}).addTo(miniMapObj);map.on("move zoom",()=>{if(!miniMapObj)return;miniMapObj.setView(map.getCenter(),Math.max(2,map.getZoom()-4),{animate:false});miniRect.setBounds(map.getBounds())})}
