function addAttributeField(){const n=prompt("اسم الحقل الجديد بالإنجليزية أو العربية:");if(!n)return;const k=safe(n,"field").replace(/\s+/g,"_");layers.eachLayer(l=>{l.feature=l.feature||{type:"Feature",properties:{}};l.feature.properties=l.feature.properties||{};if(!(k in l.feature.properties))l.feature.properties[k]=""});commit();openAttributeTable()}
