function rasterProjection(r){const p=String(r.projection||4326);return p.startsWith("EPSG:")?p:`EPSG:${p}`}function cellLonLat(r,row,col){const x=r.xmin+(col+.5)*r.pixelWidth,y=r.ymax-(row+.5)*Math.abs(r.pixelHeight);const p=rasterProjection(r);try{const q=proj4(p,"EPSG:4326",[x,y]);return q}catch{return[x,y]}}
