async function runOverlay(){const A=layerByStamp($("#overlayA").value),B=layerByStamp($("#overlayB").value),op=$("#overlayOp").value;if(!A||!B||A===B)return toast("اختر مضلعين مختلفين","warn");try{const T=await turf(),a=feature(A),b=feature(B);let out;if(op==="intersect")out=T.intersect(T.featureCollection([a,b]));else if(op==="union")out=T.union(T.featureCollection([a,b]));else out=T.difference(T.featureCollection([a,b]));if(!out)return toast("لا توجد نتيجة هندسية","warn");out.properties={customName:`${op}: ${A.customName} / ${B.customName}`,customNotes:"نتيجة تحليل مكاني داخل FMTopo Pro",customStyle:{color:"#7c3aed",fillColor:"#8b5cf6",weight:3,opacity:.95,fillOpacity:.2}};addFC(out,{fit:true});commit();toast("تم إنشاء طبقة النتيجة","ok")}catch(e){console.error(e);toast("تعذر تنفيذ العملية على هذه الهندسات","err")}}
