async function tabularToGeoJSON(f){const rows=await readJoinFile(f);if(!rows.length)throw Error("الجدول فارغ");const keys=Object.keys(rows[0]),find=(arr)=>keys.find(k=>arr.includes(k.toLowerCase().replace(/\s+/g,""))),latK=find(["lat","latitude","y_wgs84"]),lngK=find(["lng","lon","longitude","x_wgs84"]),xK=find(["x","easting","coordx"]),yK=find(["y","northing","coordy"]);if(!(latK&&lngK)&&!(xK&&yK))throw Error("يلزم وجود Lat/Lng أو X/Y في الجدول");const features=[];for(const r of rows){let lng,lat;if(latK&&lngK){lat=Number(r[latK]);lng=Number(r[lngK])}else{const q=proj4(crs,"EPSG:4326",[Number(r[xK]),Number(r[yK])]);lng=q[0];lat=q[1]}if(!Number.isFinite(lat)||!Number.isFinite(lng))continue;features.push({type:"Feature",geometry:{type:"Point",coordinates:[lng,lat]},properties:{...r,customName:String(r.name||r.nom||r.الاسم||`نقطة ${features.length+1}`)}})}return{type:"FeatureCollection",features}}
