async function checkRsService(){const box=$("#rsServiceStatus"),label=$("#rsServiceText"),api=rsApiBase();if(!box||!label)return;if(!api){box.className="rs-service error";box.querySelector("i").className="fa-solid fa-triangle-exclamation";label.textContent="شغّل المنصة عبر HTTPS واربط الخادم من إعدادات الموقع العامة.";return}box.className="rs-service checking";box.querySelector("i").className="fa-solid fa-spinner fa-spin";label.textContent="جاري التحقق من خدمة المعالجة…";const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(`${api}/health`,{cache:"no-store",signal:controller.signal});const d=await r.json().catch(()=>({}));if(!r.ok||d.ok===false)throw Error(d.error||`HTTP ${r.status}`);box.className="rs-service";box.querySelector("i").className="fa-solid fa-circle-check";label.textContent="الخدمة جاهزة؛ لا يحتاج الطالب إلى إدخال أي رابط."}catch(e){box.className="rs-service error";box.querySelector("i").className="fa-solid fa-circle-exclamation";label.textContent="الخدمة غير متاحة حالياً. تواصل مع مدير المنصة."}finally{clearTimeout(timer)}}
