function deriveRaster(kind){const r=activeRaster;if(!r)return toast("حدد DEM من قائمة الراسترات","warn");const R=r.georaster,V=rasterValues(R),w=R.width,h=R.height;if(w*h>3e6)return toast("الراستر كبير؛ قصه أولاً أو استخدم خادماً للمعالجة","warn",5000);const dx=Math.abs(R.pixelWidth)||1,dy=Math.abs(R.pixelHeight)||1,out=Array.from({length:h},()=>Array(w).fill(null));let min=Infinity,max=-Infinity;for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const z1=V[y-1][x-1],z2=V[y-1][x],z3=V[y-1][x+1],z4=V[y][x-1],z6=V[y][x+1],z7=V[y+1][x-1],z8=V[y+1][x],z9=V[y+1][x+1];if([z1,z2,z3,z4,z6,z7,z8,z9].some(z=>!Number.isFinite(z)))continue;const dzdx=((z3+2*z6+z9)-(z1+2*z4+z7))/(8*dx),dzdy=((z7+2*z8+z9)-(z1+2*z2+z3))/(8*dy),slope=Math.atan(Math.hypot(dzdx,dzdy)),aspect=Math.atan2(dzdy,-dzdx),az=315*Math.PI/180,alt=45*Math.PI/180;let v=kind==='slope'?slope*180/Math.PI:255*Math.max(0,Math.sin(alt)*Math.cos(slope)+Math.cos(alt)*Math.sin(slope)*Math.cos(az-aspect));out[y][x]=v;min=Math.min(min,v);max=Math.max(max,v)}const D={...R,values:[out],numberOfRasters:1,mins:[min],maxs:[max],ranges:[max-min],noDataValue:null};addParsedRaster(D,`${kind==='slope'?'Slope':'Hillshade'}_${r.name}`,{palette:kind==='slope'?'risk':'gray',opacity:.75})}
function showRasterStats(){if(!activeRaster)return toast("حدد راستر أولاً","warn");const s=activeRaster.stats;toast(`${activeRaster.name}: Min ${s.min.toFixed(3)} | Max ${s.max.toFixed(3)} | Mean ${s.mean.toFixed(3)} | SD ${s.std.toFixed(3)} | n=${s.count}`,"info",8000)}
function sampleRasterAt(ll,r=activeRaster){if(!r)return null;const R=r.georaster,p=rasterProjection(R);let xy;try{xy=proj4("EPSG:4326",p,[ll.lng,ll.lat])}catch{xy=[ll.lng,ll.lat]}const col=Math.floor((xy[0]-R.xmin)/R.pixelWidth),row=Math.floor((R.ymax-xy[1])/Math.abs(R.pixelHeight)),v=rasterValues(R)[row]?.[col];return{row,col,value:v}}
async function stacSearch(){const b=$("#searchStac"),from=$("#stacFrom").value,to=$("#stacTo").value;if(!from||!to)return toast("حدد تاريخ البداية والنهاية","warn");busy(b,true,"البحث...");const poly=[...layers.getLayers()].reverse().find(l=>type(l)==="Polygon"),bounds=poly?poly.getBounds():map.getBounds(),bbox=[bounds.getWest(),bounds.getSouth(),bounds.getEast(),bounds.getNorth()],collection=$("#satellite").value,cloud=+$("#cloudMax").value;try{const body={collections:[collection],bbox,datetime:`${from}T00:00:00Z/${to}T23:59:59Z`,limit:20,sortby:[{field:"datetime",direction:"desc"}]};if(collection.includes('sentinel-2'))body.query={"eo:cloud_cover":{lte:cloud}};const res=await fetch("https://earth-search.aws.element84.com/v1/search",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});if(!res.ok)throw Error(`HTTP ${res.status}`);const d=await res.json();renderStac(d.features||[])}catch(e){console.error(e);toast("تعذر الوصول إلى فهرس المشاهد","err")}finally{busy(b,false)}}
function renderStac(items){const box=$("#stacResults");box.replaceChildren();if(!items.length){box.innerHTML='<div class="empty">لا توجد مشاهد مطابقة</div>';return}items.forEach(it=>{const d=document.createElement("article");d.className="scene";const img=document.createElement("img"),thumb=it.assets?.thumbnail?.href||it.assets?.rendered_preview?.href;img.src=thumb||"";img.alt="معاينة";const c=document.createElement("div"),h=document.createElement("h4"),p=document.createElement("p");h.textContent=it.id;p.textContent=`${(it.properties.datetime||'').slice(0,10)} | السحب: ${it.properties['eo:cloud_cover']??'—'}%`;const row=document.createElement("div");row.className="row";const foot=document.createElement("button");foot.className="btn";foot.innerHTML='<i class="fa-solid fa-vector-square"></i> الحدود';foot.onclick=()=>{const f={type:'Feature',geometry:it.geometry,properties:{customName:`Scene ${it.id}`,customNotes:`${it.properties.datetime||''}; cloud=${it.properties['eo:cloud_cover']??''}`,customStyle:{color:'#ec4899',fillColor:'#ec4899',weight:2,fillOpacity:.05}}};addFC(f,{fit:true});commit()};const open=document.createElement("button");open.className="btn";open.innerHTML='<i class="fa-solid fa-arrow-up-right-from-square"></i> البيانات';open.onclick=()=>window.open(it.links?.find(x=>x.rel==='self')?.href||it.assets?.visual?.href||it.assets?.red?.href,'_blank','noopener,noreferrer');row.append(foot,open);c.append(h,p,row);d.append(img,c);box.append(d)})}
const fieldTemplates={general:[['site_name','اسم الموقع','text'],['category','الفئة','text'],['description','الوصف','textarea']],erosion:[['gully_width','عرض الخندق م','number'],['gully_depth','العمق م','number'],['slope_pct','الانحدار %','number'],['erosion_type','نوع التعرية','text'],['land_cover','الغطاء الأرضي','text']],soil:[['soil_type','نوع التربة','text'],['texture','القوام','text'],['vegetation_pct','الغطاء النباتي %','number'],['moisture','الرطوبة','text']],water:[['water_type','نوع المورد المائي','text'],['water_state','الحالة','text'],['width_m','العرض م','number'],['notes_water','ملاحظات','textarea']]};
function renderFieldForm(){const box=$("#fieldForm");box.replaceChildren();for(const[f,l,t]of fieldTemplates[$("#formTemplate").value]){const e=t==='textarea'?document.createElement('textarea'):document.createElement('input');e.className='inp';e.dataset.field=f;e.placeholder=l;if(t==='number')e.type='number';box.append(e)}}
function updateGps(p){lastGps=p;const c=p.coords,a=c.accuracy||Infinity;$("#gpsStatus").textContent=`${c.latitude.toFixed(6)}, ${c.longitude.toFixed(6)}`;$("#gpsStatus").className=`gpsval ${a<=5?'gpsgood':a<=15?'gpswarn':'gpsbad'}`;$("#gpsAcc").textContent=Math.round(a);$("#gpsAlt").textContent=Number.isFinite(c.altitude)?Math.round(c.altitude):'—';$("#gpsSpeed").textContent=Number.isFinite(c.speed)?(c.speed*3.6).toFixed(1):'—';$("#gpsHeading").textContent=Number.isFinite(c.heading)?Math.round(c.heading):'—'}
function ensureGps(){if(gpsWatch!==null)return;if(!navigator.geolocation)return toast("GPS غير مدعوم","err");gpsWatch=navigator.geolocation.watchPosition(updateGps,()=>toast("تعذر قراءة GPS","err"),{enableHighAccuracy:true,maximumAge:1000,timeout:15000})}
function gpsFeature(props={}){if(!lastGps)return toast("انتظر الحصول على إشارة GPS","warn");const c=lastGps.coords;if(c.accuracy>30&&!confirm(`دقة GPS ضعيفة ±${Math.round(c.accuracy)} م. هل تريد المتابعة؟`))return;const l=L.marker([c.latitude,c.longitude]);decorate(l,{customName:props.site_name||`نقطة ميدانية ${new Date().toLocaleTimeString('ar-MA')}`,customNotes:props.description||'',customTags:'ميدان,GPS'});l.feature={type:'Feature',properties:{...props,gps_accuracy:c.accuracy,gps_altitude:c.altitude,gps_speed:c.speed,gps_heading:c.heading,recorded_at:new Date().toISOString()}};layers.addLayer(l);lastLayer=l;commit();map.setView(l.getLatLng(),17);return l}
function saveFieldForm(){const p={};$$('#fieldForm [data-field]').forEach(e=>p[e.dataset.field]=e.value);gpsFeature(p)}
function startTrack(){ensureGps();trackPoints=[];if(trackLayer)map.removeLayer(trackLayer);trackLayer=L.polyline([],{color:'#dc2626',weight:4}).addTo(map);trackWatch=navigator.geolocation.watchPosition(p=>{updateGps(p);const c=p.coords;if(c.accuracy>50)return;const ll=L.latLng(c.latitude,c.longitude);if(!trackPoints.length||trackPoints.at(-1).distanceTo(ll)>2){trackPoints.push(ll);trackLayer.setLatLngs(trackPoints)}},()=>toast('تعذر تسجيل المسار','err'),{enableHighAccuracy:true,maximumAge:0,timeout:15000});$("#trackStart").disabled=true;$("#trackStop").disabled=false;toast('بدأ تسجيل المسار','ok')}
function stopTrack(){if(trackWatch!==null)navigator.geolocation.clearWatch(trackWatch);trackWatch=null;$("#trackStart").disabled=false;$("#trackStop").disabled=true;if(trackPoints.length>1){map.removeLayer(trackLayer);const l=L.polyline(trackPoints);decorate(l,{customName:`مسار ميداني ${new Date().toLocaleDateString('ar-MA')}`,customNotes:`عدد النقاط ${trackPoints.length}; المسافة ${(dist(l)/1000).toFixed(3)} كم`,customTags:'GPS,مسار'});layers.addLayer(l);lastLayer=l;commit()}toast('تم إيقاف المسار','info')}
function exportTrack(){if(trackPoints.length<2)return toast('لا يوجد مسار مسجل','warn');const trk=trackPoints.map(p=>`<trkpt lat="${p.lat}" lon="${p.lng}"></trkpt>`).join(''),g=`<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="FMTopo Pro" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>FMTopo Track</name><trkseg>${trk}</trkseg></trk></gpx>`;download(new Blob([g],{type:'application/gpx+xml'}),`${slug($('#projectName').value)}_track.gpx`)}
async function addPhotos(files){if(!lastLayer)return toast('حدد أو أنشئ عنصراً أولاً','warn');const id=lastLayer.featureId,arr=photoRegistry.get(id)||[];for(const f of files){if(!f.type.startsWith('image/'))continue;const u=URL.createObjectURL(f);arr.push({name:f.name,url:u,size:f.size,type:f.type})}photoRegistry.set(id,arr);lastLayer.feature=lastLayer.feature||{type:'Feature',properties:{}};lastLayer.feature.properties=lastLayer.feature.properties||{};lastLayer.feature.properties.photo_count=arr.length;renderPhotos(id);commit();toast(`تم إرفاق ${files.length} صورة محلياً`,'ok')}
function renderPhotos(id=lastLayer?.featureId){const box=$("#photoStrip");box.replaceChildren();for(const p of photoRegistry.get(id)||[]){const img=document.createElement('img');img.src=p.url;img.title=p.name;box.append(img)}}
const glossary=[['نظام المعلومات الجغرافي','Système d’information géographique','Geographic Information System','منظومة لإدارة وتحليل وعرض البيانات المرتبطة بالمكان.'],['الاستشعار عن بعد','Télédétection','Remote Sensing','الحصول على معلومات عن سطح الأرض دون تماس مباشر، غالباً بواسطة الأقمار الصناعية.'],['الراستر','Raster','Raster','شبكة من الخلايا أو البكسلات تحمل قيماً رقمية.'],['المتجه','Vecteur','Vector','تمثيل المعالم بالنقاط والخطوط والمضلعات.'],['نظام الإحداثيات','Système de coordonnées','Coordinate Reference System','إطار رياضي يحدد كيفية تمثيل المواقع على الخريطة.'],['التصحيح الجوي','Correction atmosphérique','Atmospheric Correction','تقليل أثر الغلاف الجوي على القيم الطيفية.'],['الدقة المكانية','Résolution spatiale','Spatial Resolution','حجم أصغر خلية يمكن للصورة تمثيلها.'],['NDVI','Indice de végétation normalisé','Normalized Difference Vegetation Index','مؤشر يبرز حيوية وكثافة الغطاء النباتي.'],['NDWI','Indice normalisé de l’eau','Normalized Difference Water Index','مؤشر يساعد على إبراز المسطحات المائية أو الرطوبة حسب الصيغة.'],['Zonal Statistics','Statistiques zonales','Zonal Statistics','تلخيص قيم الراستر داخل مناطق محددة.'],['Buffer','Zone tampon','Buffer','نطاق يبعد مسافة محددة عن معلم مكاني.'],['Intersect','Intersection','Intersect','استخراج المساحة أو الأجزاء المشتركة بين طبقتين.'],['DEM','Modèle numérique d’élévation','Digital Elevation Model','راستر يمثل ارتفاع سطح الأرض.'],['Flow Accumulation','Accumulation de flux','Flow Accumulation','عدد الخلايا التي تصب باتجاه كل خلية وفق نموذج الجريان.']];
