function crsHelp(){const c=map.getCenter(),lng=c.lng;let suggestion='EPSG:4326';if(c.lat>20&&c.lat<37&&lng>-18&&lng<0)suggestion=lng<-6?'EPSG:32629':'EPSG:32630';const msg=`مركز الخريطة: ${c.lat.toFixed(3)}, ${c.lng.toFixed(3)}. الاقتراح العام للبيانات الحديثة: ${suggestion}. للخرائط المغربية القديمة قد تحتاج Lambert Merchich Zone I أو II حسب المجال.`;toast(msg,'info',10000)}
async function validateProject(){const out=[],arr=layers.getLayers();if(!arr.length)out.push(['warn','لا توجد طبقات متجهة.']);const names=new Map();arr.forEach(l=>names.set(l.customName,(names.get(l.customName)||0)+1));for(const[n,c]of names)if(c>1)out.push(['warn',`الاسم «${n}» مكرر ${c} مرات.`]);arr.forEach(l=>{if(!l.customName)out.push(['err','عنصر بدون اسم.']);if(type(l)==='Polygon'&&area(l)<=0)out.push(['err',`المضلع ${l.customName} مساحته غير صالحة.`]);if(type(l)==='LineString'&&flat(l).length<2)out.push(['err',`الخط ${l.customName} غير مكتمل.`]);const c=center(l);if(Math.abs(c.lat)>90||Math.abs(c.lng)>180)out.push(['err',`العنصر ${l.customName} خارج WGS84.`])});if(!rasterRegistry.length)out.push(['warn','لا توجد طبقات Raster.']);if(!out.length)out.push(['ok','لم تُكتشف مشاكل أساسية في المشروع.']);const box=$("#qualityResults");box.innerHTML='<div class="sec">نتائج الفحص</div>';out.forEach(([t,m])=>{const d=document.createElement('div');d.className=`checkitem ${t}`;d.innerHTML=`<i class="fa-solid ${t==='ok'?'fa-circle-check':t==='warn'?'fa-triangle-exclamation':'fa-circle-xmark'}"></i>`;d.append(document.createTextNode(m));box.append(d)});toast(`اكتمل الفحص: ${out.length} ملاحظة`,'info')}
