document.onkeydown=e=>{const wr=["INPUT","TEXTAREA","SELECT"].includes(document.activeElement?.tagName);if(!wr&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="z"){e.preventDefault();e.shiftKey?redo():undo()}if(!wr&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="y"){e.preventDefault();redo()}if(e.key==="Escape"){closePanels();E.results.classList.remove("on");if(E.feature.classList.contains("on"))cancelFeature()}};
map.on("locationfound",e=>L.circleMarker(e.latlng,{radius:8,color:"#2563eb",weight:3,fillColor:"#fff",fillOpacity:1}).addTo(map).bindPopup(`موقعك التقريبي<br>الدقة: ${Math.round(e.accuracy)} م`).openPopup());map.on("locationerror",()=>toast("تعذر تحديد الموقع","err"));
